"""Benchmark cases. Each case is (category, language, [messages], checks); only the LAST reply is checked.

checks keys:  has   - every regex must match the reply (use a|b for alternatives)
              lacks - no regex may match
              max   - reply length limit in characters
All cases are asked by a fixed fictional player on a fixed fictional table (see evaluation/benchmark.py)."""

R, N, D, V, T, E, W = "rules", "roles", "night", "day", "voting", "elimination", "victory"


def c(cat, lang, msgs, **checks):
    return (cat, lang, [msgs] if isinstance(msgs, str) else list(msgs), checks)


